const root=new URL("../../",import.meta.url);
const files=await Promise.all(["ms.js","style.css","ms.html","sw.js"].map(p=>readFile(new URL(p,root),"utf8")));
const rawFront=files[0],front=stageFrontend(rawFront),style=files[1],html=files[2],sw=files[3];
const rawWorker=await readFile(new URL("worker/src/index.js",root),"utf8"),worker=stageWorker(rawWorker);
const between=(text,a,b)=>{const x=text.indexOf(a),y=text.indexOf(b,x+a.length);assert.ok(x>=0&&y>x,"missing block "+a);return text.slice(x,y)};
const visual=style.split("MS_LOWER_CLASSIC_V12")[1]||"";
function loadTiming(){const src=between(front,"function trustedLowerCompletionAt","function isCompletedUnloadOverStandard");const parse=v=>{if(!v)return null;const d=v instanceof Date?v:new Date(v);return Number.isNaN(d.getTime())?null:d};const ctx={Date,state:{standards:{"6W":45}},parseDate:parse,normalizeVehicle(){return "6W"},unloadStandard(){return 45},isDestination(row){return row.attendanceType!=="จุดดรอป"},isDrop(row){return row.attendanceType==="จุดดรอป"},confirmedEffectiveArrival(row){const route=parse(row.actualArrivalAt);if(!route)return null;return [row.actualArrivalAt,row.scheduleKitArrivalAt,row.scheduleTbrArrivalAt].map(parse).filter(Boolean).sort((a,b)=>a-b)[0]||null}};vm.createContext(ctx);vm.runInContext(src+";globalThis.fn=unloadTiming",ctx);return ctx.fn}
function loadWorkerDailyPredicate(){const src=between(worker,"function thaiDayForValue","function mergeCompletedToday");const ctx={Date,Intl,normalizeMsAttendance(value){const text=String(value||"").trim();if(text.includes("จุดดร"))return "จุดดรอป";if(text.includes("ปลายทาง"))return "ปลายทาง";if(text.includes("ต้นทาง"))return "ต้นทาง";return text}};vm.createContext(ctx);vm.runInContext(src+";globalThis.fn=isCompletedForThaiDay",ctx);return ctx.fn}
