test("backend accepted completed predicate keeps timestamp-less Destination and Drop but rejects active Origin and cancelled",()=>{const fn=loadWorkerDailyPredicate();const day="2026-09-10";const base={estimatedArrivalAt:"2026-09-09T17:10:00.000Z"};for(const attendanceType of ["ปลายทาง","จุดดรอป"]){assert.equal(fn({...base,attendanceType,unloadingState:2},day),true);assert.equal(fn({...base,attendanceType,unloadingState:2,completionObservedLive:false,completionSource:"UNKNOWN",unloadingCompletedAt:""},day),true)}assert.equal(fn({...base,attendanceType:"ปลายทาง",unloadingState:1},day),false);assert.equal(fn({...base,attendanceType:"ต้นทาง",unloadingState:2},day),false);assert.equal(fn({...base,attendanceType:"ปลายทาง",unloadingState:2,queueCancelledAt:"2026-09-09T18:00:00Z"},day),false);assert.equal(fn({...base,attendanceType:"ปลายทาง",unloadingState:2},"2026-09-09"),false)});
